    var boot_default = '/* ═══════════════════════════════════════════════════════════════════════\n   dsh-shell-kit · 启动画面（boot）\n\n   这一段由 Host 半个插件注入到 index.html 的 <head>，在 React 挂载之前\n   就已经生效，所以它必须：只用 CSS、只用内联 SVG、不依赖任何运行时。\n\n   颜色取自主题注入的 --dsh-boot-bg 与 body[data-ds-dark-theme]，这两样\n   在 ui-theme 的 boot 注入里已经设好，早于本样式表读取。\n   ═══════════════════════════════════════════════════════════════════════ */\n\nbody {\n  --sk-ink: #0f1115;\n  --sk-ink-2: #61666b;\n  --sk-grid: rgba(15, 17, 21, .05);\n}\n\nbody[data-ds-dark-theme] {\n  --sk-ink: #f9fafb;\n  --sk-ink-2: #cfd3d6;\n  --sk-grid: rgba(249, 250, 251, .045);\n}\n\n/* 自带的 loading 卡片让位：它仍是"应用是否挂载完成"的信号，只是不显示 */\n[data-dsh-boot] {\n  opacity: 0 !important;\n  pointer-events: none !important;\n}\n\n/* 万一 10 秒内应用没起来，把自带 loading 卡片还回去（本插件只负责好看，不劫持失败态） */\nhtml[data-sk-boot-bailed] [data-dsh-boot] {\n  opacity: 1 !important;\n  pointer-events: auto !important;\n}\n\n.sk-boot {\n  position: fixed;\n  inset: 0;\n  z-index: 100000;\n  display: grid;\n  place-items: center;\n  background: var(--dsh-boot-bg, #ffffff);\n  transition: opacity 280ms ease-in;\n  will-change: opacity;\n}\n\n.sk-boot[data-sk-leaving] { opacity: 0; }\n\n.sk-boot__grid {\n  position: absolute;\n  inset: 0;\n  background-image: radial-gradient(var(--sk-grid) 1px, transparent 1px);\n  background-size: 24px 24px;\n  opacity: 0;\n  animation: sk-grid-in 900ms ease-out 40ms both;\n  -webkit-mask-image: radial-gradient(58% 58% at 50% 50%, #000 20%, transparent 76%);\n          mask-image: radial-gradient(58% 58% at 50% 50%, #000 20%, transparent 76%);\n}\n\n.sk-boot__lockup {\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 20px;\n}\n\n.sk-boot__mark {\n  width: 92px;\n  height: 67.689119px; /* 92 × 17.04 / 23.16; independent of flex intrinsic sizing. */\n  flex: none;\n  display: block;\n  overflow: visible;\n  color: var(--sk-ink);\n}\n\n/* 第一笔：描边把鲸鱼轮廓画出来（pathLength=1，dash 进度与真实长度无关） */\n.sk-boot__trace {\n  fill: none;\n  stroke: currentColor;\n  stroke-width: .44;\n  stroke-linecap: round;\n  stroke-linejoin: round;\n  stroke-dasharray: 1;\n  stroke-dashoffset: 1;\n  animation: sk-trace 680ms cubic-bezier(.38, .12, .3, 1) 110ms both,\n             sk-trace-out 240ms ease-in 780ms both;\n}\n\n/* 第二笔：画完再填成实心 */\n.sk-boot__fill {\n  fill: currentColor;\n  opacity: 0;\n  animation: sk-fill-in 400ms ease-out 760ms both;\n}\n\n.sk-boot__wordmark {\n  font: 600 13px/1.2 -apple-system, "SF Pro Text", "PingFang SC", system-ui, sans-serif;\n  letter-spacing: .26em;\n  text-indent: .26em;\n  color: var(--sk-ink);\n  white-space: nowrap;\n  opacity: 0;\n  animation: sk-wm-in 520ms cubic-bezier(.22, .61, .36, 1) 950ms both;\n}\n\n.sk-boot__wordmark b {\n  font-weight: 500;\n  color: var(--sk-ink-2);\n}\n\n/* Draw mode changes paint only: no grid resampling or text-driven layout shifts. */\n@keyframes sk-grid-in { from { opacity: 0; } to { opacity: 1; } }\n@keyframes sk-trace { to { stroke-dashoffset: 0; } }\n@keyframes sk-trace-out { to { opacity: 0; } }\n@keyframes sk-fill-in { from { opacity: 0; } to { opacity: 1; } }\n@keyframes sk-wm-in { from { opacity: 0; } to { opacity: 1; } }\n\n/* The artwork below is ported from docs/boot/demo-morph.html and demo.html.\n   Namespaced classes/keyframes isolate it from the Harness and the stable draw mode. */\n.sk-boot--ocean {\n  --sk-ocean-sea-deep: #02080f;\n  --sk-ocean-sea-mid: #061a2b;\n  --sk-ocean-sea-top: #0d3a58;\n  --sk-ocean-whale: #eef7ff;\n  --sk-ocean-foam: #cbe6ff;\n  --sk-ocean-hud-dim: rgba(197, 219, 240, .62);\n  --sk-ocean-ease-out: cubic-bezier(.22, .68, .3, 1);\n  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "PingFang SC", system-ui, sans-serif;\n  color: #eef7ff;\n}\n.sk-boot--ocean {\n  position: fixed;\n  inset: 0;\n  overflow: hidden;\n  isolation: isolate;\n  background:\n    radial-gradient(120% 85% at 50% 118%, #12496c 0%, var(--sk-ocean-sea-top) 26%,\n      var(--sk-ocean-sea-mid) 52%, var(--sk-ocean-sea-deep) 78%, #010509 100%);\n}\n\n.sk-boot--ocean::before {\n  content: "";\n  position: absolute;\n  inset: 0 0 40% 0;\n  background: radial-gradient(80% 70% at 50% 100%,\n    rgba(111, 188, 255, .13), transparent 70%);\n  pointer-events: none;\n}\n\n.sk-boot-ocean__halo {\n  position: absolute;\n  left: 50%;\n  bottom: 6%;\n  width: min(78vw, 980px);\n  aspect-ratio: 1.9;\n  translate: -50% 0;\n  border-radius: 50%;\n  background: radial-gradient(closest-side,\n    rgba(126, 200, 255, .30), rgba(88, 160, 235, .10) 55%, transparent 72%);\n  filter: blur(18px);\n  animation: sk-ocean-halo calc(3.4s * var(--sk-boot-time-scale, 1)) var(--sk-ocean-ease-out) both;\n}\n\n@keyframes sk-ocean-halo {\n  0%   { opacity: 0; transform: scale(.82); }\n  45%  { opacity: 1; transform: scale(1); }\n  100% { opacity: .78; transform: scale(1.05); }\n}\n\n/* ── 海面（盖在鲸鱼上面，出水的那一下才「破水而出」） ────────────────── */\n.sk-boot-ocean__sea {\n  position: absolute;\n  inset: auto 0 0 0;\n  height: 38vh;\n  z-index: 4;\n  pointer-events: none;\n}\n\n.sk-boot-ocean__sea-fill {\n  position: absolute;\n  inset: auto 0 0 0;\n  height: 100%;\n  background: linear-gradient(to bottom,\n    rgba(30, 96, 146, 0) 0%, rgba(27, 90, 136, .55) 5%,\n    rgba(19, 68, 108, .88) 13%, rgba(12, 46, 74, .99) 26%,\n    #05131f 52%, #02080e 82%, #010508 100%);\n}\n\n.sk-boot-ocean__sea-wave {\n  position: absolute;\n  left: -25%;\n  width: 150%;\n  height: 100%;\n  display: block;\n}\n.sk-boot-ocean__sea-wave--back  { top: -1%; opacity: .38; animation: sk-ocean-drift calc(11s * var(--sk-boot-time-scale, 1)) ease-in-out infinite alternate; }\n.sk-boot-ocean__sea-wave--mid   { top: 1%;  opacity: .55; animation: sk-ocean-drift calc(8.5s * var(--sk-boot-time-scale, 1)) ease-in-out infinite alternate-reverse; }\n.sk-boot-ocean__sea-wave--front { top: 3%;  opacity: .95; animation: sk-ocean-drift calc(6.4s * var(--sk-boot-time-scale, 1)) ease-in-out infinite alternate; }\n\n.sk-boot-ocean__sea-wave path {\n  fill: #061a2b;\n  stroke: rgba(176, 222, 255, .30);\n  stroke-width: 1.1;\n  vector-effect: non-scaling-stroke;\n}\n.sk-boot-ocean__sea-wave--back  path { fill: #0c3550; stroke: rgba(170, 216, 255, .18); }\n.sk-boot-ocean__sea-wave--mid   path { fill: #08283f; stroke: rgba(176, 222, 255, .26); }\n.sk-boot-ocean__sea-wave--front path { stroke: rgba(198, 232, 255, .45); }\n\n@keyframes sk-ocean-drift {\n  from { transform: translateX(-3.5%) translateY(0); }\n  to   { transform: translateX(3.5%) translateY(-1.4%); }\n}\n\n.sk-boot-ocean__sea-mist {\n  position: absolute;\n  inset: -26px 0 auto 0;\n  height: 90px;\n  background: linear-gradient(to top, rgba(120, 186, 240, .16), transparent 78%);\n  filter: blur(7px);\n}\n\n.sk-boot-ocean__sea-shine {\n  position: absolute;\n  left: 50%;\n  top: -2px;\n  width: min(46vw, 560px);\n  height: 3px;\n  translate: -50% 0;\n  border-radius: 50%;\n  background: linear-gradient(90deg, transparent, rgba(190, 228, 255, .85), transparent);\n  filter: blur(2px);\n  animation: sk-ocean-shine calc(3.4s * var(--sk-boot-time-scale, 1)) var(--sk-ocean-ease-out) both;\n}\n@keyframes sk-ocean-shine { 0%, 12% { opacity: 0; } 55% { opacity: .9; } 100% { opacity: .5; } }\n\n/* ── 主角：鲸鱼 → logo ──────────────────────────────────────────────── */\n.sk-boot-ocean__stage {\n  position: absolute;\n  inset: 0;\n  z-index: 2;             /* 低于 .sk-boot-ocean__sea：起飞那一下会被海面挡住 */\n  display: grid;\n  place-items: center;\n  pointer-events: none;\n}\n\n/*\n * lockup 就是动画结束时的最终状态：品牌标 + 字标，水平居中锁死。\n * 鲸鱼三层 wrapper 各自把「位移 / 姿态与缩放」从起始值归零，\n * 归零之后它天然就落在 logo 的位置上 —— 不需要算像素。\n */\n.sk-boot-ocean__lockup {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  transform-origin: 50% 50%;\n  animation: sk-ocean-lock-shake calc(520ms * var(--sk-boot-time-scale, 1)) cubic-bezier(.36, .07, .19, .97) calc(1490ms * var(--sk-boot-time-scale, 1)) both;\n}\n\n.sk-boot-ocean__arc-x {\n  animation: sk-ocean-arc-x calc(1280ms * var(--sk-boot-time-scale, 1)) cubic-bezier(.32, .02, .5, 1) calc(220ms * var(--sk-boot-time-scale, 1)) both;\n  will-change: transform;\n}\n\n.sk-boot-ocean__arc-y {\n  animation: sk-ocean-arc-y calc(1280ms * var(--sk-boot-time-scale, 1)) cubic-bezier(.34, .02, .46, 1) calc(220ms * var(--sk-boot-time-scale, 1)) both;\n  will-change: transform;\n}\n\n.sk-boot-ocean__arc-rot {\n  animation: sk-ocean-arc-rot calc(1280ms * var(--sk-boot-time-scale, 1)) cubic-bezier(.3, .02, .5, 1) calc(220ms * var(--sk-boot-time-scale, 1)) both;\n  will-change: transform;\n}\n\n.sk-boot-ocean__mark {\n  display: block;\n  width: 84px;\n  height: auto;\n  color: var(--sk-ocean-whale);\n  /* 鲸鱼本来朝左；翻转写在元素自身，父级 rotate 才不会被镜像 */\n  transform: scaleX(-1);\n  filter:\n    drop-shadow(0 0 10px rgba(150, 210, 255, .55))\n    drop-shadow(0 0 34px rgba(96, 168, 255, .34));\n}\n\n/* 横向：从左下角飞向中心 */\n@keyframes sk-ocean-arc-x {\n  0%   { transform: translateX(-40vw); }\n  100% { transform: translateX(0); }\n}\n\n/* 纵向：出水 → 过冲一点点 → 落到中心 */\n@keyframes sk-ocean-arc-y {\n  0%   { transform: translateY(44vh); }\n  46%  { transform: translateY(-5vh); }\n  68%  { transform: translateY(-8vh); }\n  86%  { transform: translateY(1.2vh); }\n  100% { transform: translateY(0); }\n}\n\n/* 姿态 + 缩放：昂头起飞 → 放平 → 收成 logo 尺寸（末段轻微过冲） */\n@keyframes sk-ocean-arc-rot {\n  0%   { transform: rotate(-40deg) scale(2.9); }\n  24%  { transform: rotate(-22deg) scale(2.72); }\n  48%  { transform: rotate(-4deg) scale(2.3); }\n  74%  { transform: rotate(7deg) scale(1.42); }\n  90%  { transform: rotate(-2.5deg) scale(.93); }\n  100% { transform: rotate(0deg) scale(1); }\n}\n\n/* 「抖一下」：落定后的三下渐弱冲击 */\n@keyframes sk-ocean-lock-shake {\n  0%   { transform: translate(0, 0) rotate(0deg) scale(1); }\n  12%  { transform: translate(-4px, 3px) rotate(-1.6deg) scale(1.05); }\n  28%  { transform: translate(4px, -3px) rotate(1.4deg) scale(1.03); }\n  44%  { transform: translate(-3px, 1.6px) rotate(-.9deg) scale(1.016); }\n  60%  { transform: translate(2px, -1.2px) rotate(.6deg) scale(1.008); }\n  78%  { transform: translate(-1px, .6px) rotate(-.28deg) scale(1.003); }\n  100% { transform: translate(0, 0) rotate(0deg) scale(1); }\n}\n\n/* ── 字标 ───────────────────────────────────────────────────────────── */\n.sk-boot-ocean__wordmark {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  white-space: nowrap;\n  opacity: 0;\n  animation: sk-ocean-wordmark-in calc(620ms * var(--sk-boot-time-scale, 1)) var(--sk-ocean-ease-out) calc(1500ms * var(--sk-boot-time-scale, 1)) both;\n}\n\n.sk-boot-ocean__wordmark-name {\n  font-size: 19px;\n  font-weight: 650;\n  letter-spacing: .34em;\n  text-transform: uppercase;\n  color: #fff;\n  animation: sk-ocean-tracking calc(620ms * var(--sk-boot-time-scale, 1)) var(--sk-ocean-ease-out) calc(1500ms * var(--sk-boot-time-scale, 1)) both;\n}\n\n.sk-boot-ocean__wordmark-suffix {\n  padding: 2px 7px 3px;\n  border: 1px solid rgba(255, 255, 255, .5);\n  border-radius: 3px;\n  font-size: 10px;\n  font-weight: 600;\n  letter-spacing: .16em;\n  color: rgba(255, 255, 255, .82);\n}\n\n@keyframes sk-ocean-wordmark-in {\n  0%   { opacity: 0; filter: blur(10px); transform: translateX(-10px); }\n  100% { opacity: 1; filter: blur(0); transform: translateX(0); }\n}\n\n@keyframes sk-ocean-tracking {\n  0%   { letter-spacing: .34em; opacity: .4; }\n  100% { letter-spacing: .14em; opacity: 1; }\n}\n\n/* ── 落定瞬间的闪光与冲击波 ──────────────────────────────────────────── */\n.sk-boot-ocean__mark-slot {\n  position: relative;\n  width: 84px;\n  height: 84px;\n  display: grid;\n  place-items: center;\n  flex: none;\n}\n\n.sk-boot-ocean__shock-layer {\n  position: absolute;\n  inset: 0;\n  z-index: 6;\n  pointer-events: none;\n}\n\n.sk-boot-ocean__shock {\n  position: absolute;\n  width: 84px;\n  height: 84px;\n  margin: -42px 0 0 -42px;\n  border-radius: 50%;\n  border: 1.5px solid rgba(198, 232, 255, .85);\n  opacity: 0;\n  z-index: 5;\n  pointer-events: none;\n  animation: sk-ocean-shock calc(1100ms * var(--sk-boot-time-scale, 1)) cubic-bezier(.2, .7, .35, 1) both;\n}\n\n@keyframes sk-ocean-shock {\n  0%   { transform: scale(.35); opacity: 0; }\n  14%  { opacity: .95; }\n  100% { transform: scale(4.6); opacity: 0; }\n}\n\n.sk-boot-ocean__flash {\n  position: absolute;\n  inset: 0;\n  z-index: 8;\n  background: radial-gradient(34% 24% at 50% 50%, rgba(226, 243, 255, .62), rgba(200, 232, 255, 0) 70%);\n  opacity: 0;\n  pointer-events: none;\n  animation: sk-ocean-flash calc(560ms * var(--sk-boot-time-scale, 1)) ease-out calc(1490ms * var(--sk-boot-time-scale, 1)) both;\n}\n@keyframes sk-ocean-flash {\n  0%   { opacity: 0; }\n  12%  { opacity: .8; }\n  38%  { opacity: .35; }\n  100% { opacity: 0; }\n}\n\n/* ── 水花 ───────────────────────────────────────────────────────────── */\n.sk-boot-ocean__fx {\n  position: absolute;\n  inset: 0;\n  z-index: 6;\n  pointer-events: none;\n}\n\n.sk-boot-ocean__drop {\n  position: absolute;\n  width: var(--s, 6px);\n  height: var(--s, 6px);\n  border-radius: 50%;\n  background: radial-gradient(circle at 35% 30%, #fff, var(--sk-ocean-foam) 60%, rgba(150, 200, 240, .2));\n  opacity: 0;\n  animation: sk-ocean-drop var(--dur, calc(900ms * var(--sk-boot-time-scale, 1))) cubic-bezier(.16, .7, .4, 1) var(--delay, calc(0ms * var(--sk-boot-time-scale, 1))) both;\n}\n\n@keyframes sk-ocean-drop {\n  0%   { transform: translate(0, 0) scale(.5); opacity: 0; }\n  12%  { opacity: 1; }\n  52%  { transform: translate(var(--dx, 0px), calc(-1 * var(--up, 90px))) scale(1); opacity: 1; }\n  100% { transform: translate(var(--dx2, 0px), var(--down, 24px)) scale(.35); opacity: 0; }\n}\n\n.sk-boot-ocean__foam {\n  position: absolute;\n  width: 120px;\n  height: 40px;\n  margin: -20px 0 0 -60px;\n  border-radius: 50%;\n  background: radial-gradient(closest-side, #ffffff, rgba(196, 232, 255, .55) 45%, transparent 72%);\n  filter: blur(5px);\n  opacity: 0;\n  animation: sk-ocean-foam calc(880ms * var(--sk-boot-time-scale, 1)) cubic-bezier(.2, .7, .4, 1) var(--delay, calc(0ms * var(--sk-boot-time-scale, 1))) both;\n}\n@keyframes sk-ocean-foam {\n  0%   { transform: scale(.25); opacity: .95; }\n  55%  { transform: scale(1.15); opacity: .55; }\n  100% { transform: scale(2.2); opacity: 0; }\n}\n\n.sk-boot-ocean__ripple {\n  position: absolute;\n  width: 40px;\n  height: 12px;\n  margin-left: -20px;\n  border: 1.5px solid rgba(186, 226, 255, .6);\n  border-radius: 50%;\n  opacity: 0;\n  animation: sk-ocean-ripple calc(1500ms * var(--sk-boot-time-scale, 1)) cubic-bezier(.2, .7, .35, 1) var(--delay, calc(0ms * var(--sk-boot-time-scale, 1))) both;\n}\n@keyframes sk-ocean-ripple {\n  0%   { transform: scale(.25); opacity: 0; }\n  18%  { opacity: .85; }\n  100% { transform: scale(9); opacity: 0; }\n}\n\n\n.sk-boot-ocean__hud {\n  position: absolute;\n  left: 50%;\n  bottom: 12vh;\n  translate: -50% 0;\n  z-index: 7;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 12px;\n  text-align: center;\n}\n\n.sk-boot-ocean__meter {\n  width: min(340px, 56vw);\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  opacity: 0;\n  animation: sk-ocean-rise calc(700ms * var(--sk-boot-time-scale, 1)) var(--sk-ocean-ease-out) calc(1750ms * var(--sk-boot-time-scale, 1)) both;\n}\n\n.sk-boot-ocean__meter-track {\n  position: relative;\n  flex: 1;\n  height: 2px;\n  border-radius: 2px;\n  background: rgba(190, 222, 250, .16);\n  overflow: hidden;\n}\n\n.sk-boot-ocean__meter-bar {\n  position: absolute;\n  inset: 0 auto 0 0;\n  width: 0%;\n  border-radius: inherit;\n  background: linear-gradient(90deg, rgba(140, 205, 255, .55), #fff);\n  box-shadow: 0 0 12px rgba(140, 205, 255, .8);\n  transition: width calc(560ms * var(--sk-boot-time-scale, 1)) var(--sk-ocean-ease-out);\n}\n\n@keyframes sk-ocean-rise {\n  0%   { opacity: 0; transform: translateY(6px); }\n  100% { opacity: 1; transform: translateY(0); }\n}\n\n\n.sk-boot-ocean__whale-track {\n  position: absolute;\n  left: 6vw;\n  bottom: 24vh;\n  z-index: 2;               /* 低于 .sk-boot-ocean__sea，海面才会盖住它 */\n  animation: sk-ocean-whale-x calc(2.5s * var(--sk-boot-time-scale, 1)) cubic-bezier(.32, .02, .62, 1) calc(.3s * var(--sk-boot-time-scale, 1)) both;\n}\n\n.sk-boot-ocean__whale-lift {\n  animation: sk-ocean-whale-y calc(2.5s * var(--sk-boot-time-scale, 1)) cubic-bezier(.38, .02, .45, 1) calc(.3s * var(--sk-boot-time-scale, 1)) both;\n}\n\n.sk-boot-ocean__whale-tilt {\n  animation: sk-ocean-whale-tilt calc(2.5s * var(--sk-boot-time-scale, 1)) cubic-bezier(.3, .02, .5, 1) calc(.3s * var(--sk-boot-time-scale, 1)) both;\n}\n\n.sk-boot-ocean__whale {\n  display: block;\n  width: clamp(150px, 18vw, 262px);\n  height: auto;\n  color: var(--sk-ocean-whale);\n  /* 鲸鱼本来朝左，翻过来朝右飞。\n     必须翻转在元素自身上（transform），不能写在父级的 scale 属性上，\n     否则父级的 rotate 会被一并镜像，姿态方向会反。 */\n  transform: scaleX(-1);\n  filter:\n    drop-shadow(0 0 12px rgba(150, 210, 255, .55))\n    drop-shadow(0 0 42px rgba(96, 168, 255, .32));\n}\n\n/* 横向：匀速穿越画面 */\n@keyframes sk-ocean-whale-x {\n  0%   { transform: translateX(0); }\n  100% { transform: translateX(62vw); }\n}\n\n/* 纵向：出水 → 顶点悬停 → 落回 */\n@keyframes sk-ocean-whale-y {\n  0%   { transform: translateY(34vh); }\n  34%  { transform: translateY(-4vh); }\n  50%  { transform: translateY(-12vh); }\n  66%  { transform: translateY(-3vh); }\n  100% { transform: translateY(32vh); }\n}\n\n/* 姿态：出水时昂头，顶点放平，入水时低头 */\n@keyframes sk-ocean-whale-tilt {\n  0%   { transform: rotate(-34deg); }\n  32%  { transform: rotate(-12deg); }\n  52%  { transform: rotate(6deg); }\n  72%  { transform: rotate(28deg); }\n  100% { transform: rotate(44deg); }\n}\n\n\n.sk-boot-ocean__brand {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  animation: sk-ocean-brand-in calc(1100ms * var(--sk-boot-time-scale, 1)) var(--sk-ocean-ease-out) calc(1200ms * var(--sk-boot-time-scale, 1)) both;\n}\n\n.sk-boot-ocean__brand-mark {\n  width: 34px;\n  height: auto;\n  color: #fff;\n  filter: drop-shadow(0 0 14px rgba(140, 205, 255, .6));\n}\n\n.sk-boot-ocean__brand-text {\n  display: flex;\n  align-items: baseline;\n  gap: 12px;\n  font-size: 15px;\n  letter-spacing: .44em;          /* 首帧字距很大，收拢到 .17em */\n  text-transform: uppercase;\n  color: #fff;\n  animation: sk-ocean-brand-tracking calc(1400ms * var(--sk-boot-time-scale, 1)) var(--sk-ocean-ease-out) calc(1200ms * var(--sk-boot-time-scale, 1)) both;\n}\n\n.sk-boot-ocean__brand-name { font-weight: 650; }\n.sk-boot-ocean__brand-suffix {\n  padding: 2px 7px 3px;\n  border: 1px solid rgba(255, 255, 255, .5);\n  border-radius: 3px;\n  font-size: 10px;\n  font-weight: 600;\n  letter-spacing: .16em;\n  color: rgba(255, 255, 255, .82);\n}\n\n@keyframes sk-ocean-brand-in {\n  0%   { opacity: 0; filter: blur(10px); transform: translateY(8px); }\n  100% { opacity: 1; filter: blur(0); transform: translateY(0); }\n}\n\n@keyframes sk-ocean-brand-tracking {\n  0%   { letter-spacing: .44em; opacity: 0; filter: blur(8px); }\n  100% { letter-spacing: .17em; opacity: 1; filter: blur(0); }\n}\n\n\n/* Desktop and the smaller iframe use the same responsive composition. */\n.sk-boot-ocean__lockup { gap: clamp(6px, 1.2vw, 14px); }\n.sk-boot-ocean__mark-slot { width: clamp(34px, 7.2vw, 84px); height: clamp(34px, 7.2vw, 84px); }\n.sk-boot-ocean__mark { width: 100%; }\n.sk-boot-ocean__wordmark-name { font-size: clamp(10px, 1.6vw, 19px); }\n.sk-boot-ocean__wordmark-suffix { font-size: clamp(7px, .85vw, 10px); }\n.sk-boot-ocean__wordmark { gap: clamp(6px, 1vw, 12px); }\n.sk-boot-ocean__shock { left: 50%; top: 50%; animation-delay: calc(var(--delay) * var(--sk-boot-time-scale, 1)); }\n.sk-boot-ocean__splash { position: absolute; width: 0; height: 0; }\n.sk-boot-ocean__drop, .sk-boot-ocean__foam, .sk-boot-ocean__ripple { left: 0; top: 0; }\n.sk-boot-ocean__drop { animation-duration: calc(var(--dur, 900ms) * var(--sk-boot-time-scale, 1)); animation-delay: calc(var(--delay, 0ms) * var(--sk-boot-time-scale, 1)); }\n.sk-boot-ocean__foam, .sk-boot-ocean__ripple { animation-delay: calc(var(--delay, 0ms) * var(--sk-boot-time-scale, 1)); }\n.sk-boot-ocean__status { font-size: 12px; letter-spacing: .12em; color: var(--sk-ocean-hud-dim); animation: sk-ocean-rise calc(700ms * var(--sk-boot-time-scale, 1)) ease-out calc(1820ms * var(--sk-boot-time-scale, 1)) both; }\n.sk-boot-ocean__meter-bar { animation: sk-ocean-progress calc(1900ms * var(--sk-boot-time-scale, 1)) ease-out calc(1400ms * var(--sk-boot-time-scale, 1)) both; }\n@keyframes sk-ocean-progress { from { width: 0; } to { width: 88%; } }\n.sk-boot[data-sk-ready] .sk-boot-ocean__meter-bar { animation: none; width: 100%; }\n.sk-boot[data-sk-animation="abyss"] .sk-boot-ocean__hud { bottom: 7vh; gap: clamp(8px, 2vh, 18px); }\n.sk-boot[data-sk-animation="abyss"] .sk-boot-ocean__wordmark { opacity: 1; }\n.sk-boot-ocean__brand-text { font-size: clamp(10px, 1.4vw, 15px); }\n.sk-boot-ocean__brand-suffix { font-size: clamp(7px, .85vw, 10px); align-self: center; }\n.sk-boot[data-sk-animation="abyss"] .sk-boot-ocean__flash { animation: none; }\n.sk-boot[data-sk-animation="abyss"][data-sk-ready] .sk-boot-ocean__flash { animation: sk-ocean-flash 280ms ease-out both; }\n.sk-boot[data-sk-wordmark="false"] :is(.sk-boot__wordmark, .sk-boot-ocean__wordmark) { display: none; }\n.sk-boot[data-sk-theme="light"] { --dsh-boot-bg: #f4fbfa; --sk-ink: #10292a; --sk-ink-2: #3d7471; --sk-grid: rgba(16,41,42,.08); }\n.sk-boot[data-sk-theme="dark"] { --dsh-boot-bg: #101a1d; --sk-ink: #e5faf4; --sk-ink-2: #a8c9c1; --sk-grid: rgba(229,250,244,.08); }\n.sk-boot--ocean[data-sk-theme="light"], body[data-ds-light-theme] .sk-boot--ocean[data-sk-theme="auto"] {\n  --sk-ocean-sea-deep: #d2e9f3; --sk-ocean-sea-mid: #a4d0e6; --sk-ocean-sea-top: #65b3da;\n  --sk-ocean-whale: #143953; --sk-ocean-hud-dim: #d5edff;\n}\n@media (prefers-color-scheme: dark) {\n  .sk-boot[data-sk-theme="auto"] { --dsh-boot-bg: #101a1d; --sk-ink: #e5faf4; --sk-ink-2: #a8c9c1; --sk-grid: rgba(229,250,244,.08); }\n}\n@media (prefers-color-scheme: light) {\n  .sk-boot--ocean[data-sk-theme="auto"] { --sk-ocean-sea-deep: #d2e9f3; --sk-ocean-sea-mid: #a4d0e6; --sk-ocean-sea-top: #65b3da; --sk-ocean-whale: #143953; --sk-ocean-hud-dim: #d5edff; }\n}\nbody[data-ds-dark-theme] .sk-boot--ocean[data-sk-theme="auto"] { --sk-ocean-sea-deep: #02080f; --sk-ocean-sea-mid: #061a2b; --sk-ocean-sea-top: #0d3a58; --sk-ocean-whale: #eef7ff; --sk-ocean-hud-dim: rgba(197,219,240,.62); }\n@media (max-width: 700px) {\n  .sk-boot-ocean__whale { width: clamp(74px, 18vw, 150px); }\n  .sk-boot-ocean__splash { transform: scale(.55); }\n  .sk-boot-ocean__shock { width: 44px; height: 44px; margin: -22px 0 0 -22px; }\n  .sk-boot-ocean__status { font-size: 10px; }\n  .sk-boot-ocean__brand { gap: 8px; }\n  .sk-boot-ocean__brand-mark { width: 24px; }\n}\n/* No movement or flashing under the OS preference; leave the final identity readable. */\n@media (prefers-reduced-motion: reduce) {\n  .sk-boot *, .sk-boot::before, .sk-boot::after { animation: none !important; transition: none !important; }\n  .sk-boot .sk-boot__fill, .sk-boot .sk-boot__wordmark, .sk-boot .sk-boot__grid,\n  .sk-boot-ocean__wordmark, .sk-boot-ocean__wordmark-name, .sk-boot-ocean__meter, .sk-boot-ocean__status { opacity: 1; filter: none; }\n  .sk-boot .sk-boot__trace, .sk-boot-ocean__fx, .sk-boot-ocean__flash, .sk-boot-ocean__shock-layer, .sk-boot-ocean__whale-track { display: none; }\n  .sk-boot-ocean__lockup, .sk-boot-ocean__arc-x, .sk-boot-ocean__arc-y, .sk-boot-ocean__arc-rot { transform: none; }\n  .sk-boot-ocean__meter-bar { width: 88%; }\n}\n';

